import OBR from "@owlbear-rodeo/sdk";
import { DEFAULT_SETTINGS, STATUS_LABELS } from "../config";
import { importCrisCharacter } from "../cris/importer";
import type { AppSettings, CharacterSection, CharacterSheet, CharacterStatus, SceneState, TokenSummary } from "../types";
import { asRecord, escapeHtml, formatDate, safeHttpsUrl, stringifyUnknown, timeAgo } from "../utils/safe";
import { CharacterRepository } from "../storage/repository";
import { getCharacterTokens, linkTokenToCharacter } from "../owlbear/tokens";

const VITAL_SYMBOLS: Record<string, string> = { hp: "PV", pe: "PE", san: "SAN", dt: "DT" };
const ALL_STATUSES = Object.keys(STATUS_LABELS) as CharacterStatus[];

type View = "library" | "settings";

export class CharacterApp {
  private readonly root: HTMLElement;
  private readonly repository = new CharacterRepository();
  private role: "GM" | "PLAYER" = "PLAYER";
  private isOwlbear = false;
  private sceneReady = false;
  private view: View = "library";
  private activeCharacterId?: string;
  private tokenIdFromPopover?: string;
  private selectedTokenId?: string;
  private tokens: TokenSummary[] = [];
  private showImportForm = true;
  private busy = false;
  private toast?: { kind: "success" | "error" | "warning" | "info"; message: string };
  private unsubscribeRepository?: () => void;
  private unsubscribeSceneReady?: () => void;
  private autoRefreshTimer?: number;
  private refreshInProgress = false;

  constructor(root: HTMLElement) {
    this.root = root;
    this.tokenIdFromPopover = new URLSearchParams(window.location.search).get("tokenId") ?? undefined;
  }

  async init(): Promise<void> {
    this.bindEvents();
    if (OBR.isAvailable) {
      this.isOwlbear = true;
      await new Promise<void>((resolve) => OBR.onReady(() => resolve()));
      try {
        this.role = await OBR.player.getRole();
      } catch {
        this.role = "PLAYER";
      }
      try {
        const { registerTokenContextMenu } = await import("../owlbear/tokens");
        await registerTokenContextMenu();
      } catch (error) {
        console.warn("[Sistema-Cris] Não foi possível registrar o menu contextual.", error);
      }
    }

    await this.repository.load();
    this.unsubscribeRepository = this.repository.subscribe((state) => {
      if (this.activeCharacterId && !state.characters[this.activeCharacterId]) {
        this.activeCharacterId = undefined;
      }
      this.render(state);
    });

    if (this.isOwlbear) {
      await this.refreshSceneStatus();
      this.unsubscribeSceneReady = OBR.scene.onReadyChange((ready) => {
        this.sceneReady = ready;
        if (ready) {
          void this.repository.load().then(() => this.loadTokensAndTokenCharacter());
        } else {
          this.tokens = [];
          this.render(this.repository.snapshot);
        }
      });
      await this.loadTokensAndTokenCharacter();
    }

    this.configureAutoRefresh(this.repository.snapshot.settings.autoRefreshMinutes);
    this.render(this.repository.snapshot);
  }

  private bindEvents(): void {
    this.root.addEventListener("submit", (event) => {
      const target = event.target;
      if (target instanceof HTMLFormElement && target.id === "import-form") {
        event.preventDefault();
        void this.handleImport(target);
      }
    });

    this.root.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      const control = target.closest<HTMLElement>("[data-action], [data-open]");
      if (!control) return;

      const openId = control.dataset.open;
      if (openId) {
        this.activeCharacterId = openId;
        this.view = "library";
        this.render(this.repository.snapshot);
        return;
      }

      const action = control.dataset.action;
      if (!action) return;
      switch (action) {
        case "toggle-import":
          this.showImportForm = !this.showImportForm;
          this.render(this.repository.snapshot);
          break;
        case "settings":
          this.view = "settings";
          this.activeCharacterId = undefined;
          this.render(this.repository.snapshot);
          break;
        case "library":
          this.view = "library";
          this.activeCharacterId = undefined;
          this.render(this.repository.snapshot);
          break;
        case "back":
          this.activeCharacterId = undefined;
          this.render(this.repository.snapshot);
          break;
        case "refresh":
          if (this.activeCharacterId) void this.refreshCharacter(this.activeCharacterId);
          break;
        case "remove":
          if (this.activeCharacterId) void this.removeCharacter(this.activeCharacterId);
          break;
        case "link-token":
          if (this.activeCharacterId) void this.linkActiveCharacter();
          break;
        case "vital-minus":
        case "vital-plus": {
          const vitalId = control.dataset.vital;
          const delta = action === "vital-plus" ? 1 : -1;
          if (this.activeCharacterId && vitalId) void this.adjustVital(this.activeCharacterId, vitalId, delta);
          break;
        }
        case "status":
          break;
      }
    });

    this.root.addEventListener("change", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement || target instanceof HTMLTextAreaElement)) return;
      if (target instanceof HTMLSelectElement && target.dataset.setting) {
        void this.changeSetting(target.dataset.setting, target.value);
      }
      if (target instanceof HTMLSelectElement && target.id === "token-picker") {
        this.selectedTokenId = target.value || undefined;
      }
      if (target instanceof HTMLSelectElement && target.id === "character-status" && this.activeCharacterId) {
        void this.changeStatus(this.activeCharacterId, target.value as CharacterStatus);
      }
      if (target instanceof HTMLInputElement && target.dataset.vitalInput && this.activeCharacterId) {
        const value = Number(target.value);
        if (Number.isFinite(value)) void this.setVital(this.activeCharacterId, target.dataset.vitalInput, value);
      }
    });
  }

  private async refreshSceneStatus(): Promise<void> {
    try {
      this.sceneReady = await OBR.scene.isReady();
    } catch {
      this.sceneReady = false;
    }
  }

  private async loadTokensAndTokenCharacter(): Promise<void> {
    if (!this.isOwlbear || !this.sceneReady) return;
    try {
      this.tokens = await getCharacterTokens();
      if (this.tokenIdFromPopover) {
        const token = this.tokens.find((item) => item.id === this.tokenIdFromPopover);
        if (token?.characterId && this.repository.snapshot.characters[token.characterId]) {
          this.activeCharacterId = token.characterId;
        } else {
          this.selectedTokenId = this.tokenIdFromPopover;
          this.toast = {
            kind: "info",
            message: "Token selecionado sem ficha vinculada. Escolha um agente e use Vincular ao Token.",
          };
        }
      }
    } catch (error) {
      console.warn("[Sistema-Cris] Falha ao carregar Tokens.", error);
      this.tokens = [];
    }
    this.render(this.repository.snapshot);
  }

  private async handleImport(form: HTMLFormElement): Promise<void> {
    if (!this.canManage()) return;
    const formData = new FormData(form);
    const label = String(formData.get("characterName") ?? "").trim();
    const url = String(formData.get("crisUrl") ?? "").trim();
    if (!url) {
      this.showToast("error", "Cole o link público da ficha do CRIS.");
      return;
    }

    this.busy = true;
    this.toast = { kind: "info", message: "Consultando a fonte pública do CRIS…" };
    this.render(this.repository.snapshot);
    try {
      const result = await importCrisCharacter(url);
      const existing = Object.values(this.repository.snapshot.characters).find(
        (character) => character.source.recordId === result.character.source.recordId,
      );
      const incoming = result.character;
      const character: CharacterSheet = {
        ...incoming,
        id: existing?.id ?? incoming.id,
        ...(label ? { customName: label } : existing?.customName ? { customName: existing.customName } : {}),
        session: existing?.session ?? incoming.session,
        source: {
          ...incoming.source,
          importedAt: existing?.source.importedAt ?? incoming.source.importedAt,
          refreshedAt: Date.now(),
        },
      };
      await this.repository.upsert(character);
      this.activeCharacterId = character.id;
      this.view = "library";
      this.showImportForm = false;
      this.busy = false;
      this.showToast("success", existing ? "Ficha atualizada; a associação com o Token foi mantida." : "Ficha importada e adicionada ao arquivo da cena.");
      if (result.warnings.length) {
        this.showToast("warning", result.warnings[0]);
      }
    } catch (error) {
      this.busy = false;
      const message = error instanceof Error ? error.message : "Falha inesperada durante a importação.";
      this.showToast("error", message);
    }
  }

  private async refreshCharacter(id: string): Promise<void> {
    if (!this.canManage()) return;
    const existing = this.repository.snapshot.characters[id];
    if (!existing) return;
    this.busy = true;
    this.showToast("info", `Atualizando ${existing.customName || existing.identity.name}…`);
    try {
      const result = await importCrisCharacter(existing.source.url);
      const refreshed: CharacterSheet = {
        ...result.character,
        id: existing.id,
        ...(existing.customName ? { customName: existing.customName } : {}),
        session: existing.session,
        source: {
          ...result.character.source,
          importedAt: existing.source.importedAt,
          refreshedAt: Date.now(),
        },
      };
      await this.repository.upsert(refreshed);
      this.showToast("success", "Ficha atualizada. O estado temporário da sessão e a vinculação do Token foram preservados.");
      if (result.warnings.length) this.showToast("warning", result.warnings[0]);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Falha ao atualizar a ficha.";
      this.showToast("warning", `${message} Exibindo a última versão em cache.`);
    } finally {
      this.busy = false;
      this.render(this.repository.snapshot);
    }
  }

  private async removeCharacter(id: string): Promise<void> {
    if (!this.canManage()) return;
    const character = this.repository.snapshot.characters[id];
    if (!character || !window.confirm(`Remover ${character.customName || character.identity.name} desta cena?`)) return;
    try {
      const bound = this.tokens.filter((token) => token.characterId === id);
      for (const token of bound) {
        try {
          const items = await OBR.scene.items.getItems([token.id]);
          if (items.length) {
            await OBR.scene.items.updateItems(items, (draftItems) => {
              for (const item of draftItems) delete item.metadata["com.onze1onze.conexao-cris/character"];
            });
          }
        } catch {
          // A ficha é removida mesmo se um Token não puder ser atualizado.
        }
      }
      await this.repository.remove(id);
      this.activeCharacterId = undefined;
      await this.loadTokensAndTokenCharacter();
      this.showToast("success", "Ficha removida. Os Tokens vinculados foram liberados quando estavam acessíveis.");
    } catch (error) {
      this.showToast("error", error instanceof Error ? error.message : "Não foi possível remover a ficha.");
    }
  }

  private async linkActiveCharacter(): Promise<void> {
    if (!this.canManage() || !this.activeCharacterId) return;
    let tokenId = this.selectedTokenId ?? this.tokenIdFromPopover;
    if (!tokenId && this.isOwlbear) {
      try {
        const selection = await OBR.player.getSelection();
        if (selection?.length === 1) tokenId = selection[0];
      } catch {
        // A lista explícita de Tokens continua disponível como alternativa.
      }
    }
    if (!tokenId) {
      this.showToast("warning", "Selecione um Token ou escolha um na lista antes de vincular.");
      return;
    }
    try {
      await linkTokenToCharacter(tokenId, this.activeCharacterId);
      this.selectedTokenId = tokenId;
      await this.loadTokensAndTokenCharacter();
      this.showToast("success", "Token vinculado ao agente.");
    } catch (error) {
      this.showToast("error", error instanceof Error ? error.message : "Não foi possível vincular o Token.");
    }
  }

  private async adjustVital(id: string, vitalId: string, delta: number): Promise<void> {
    const character = this.repository.snapshot.characters[id];
    const vital = character?.vitals.find((item) => item.id === vitalId);
    if (!character || !vital || !this.canManage()) return;
    const current = character.session.vitalOverrides[vitalId] ?? vital.current;
    await this.setVital(id, vitalId, current + delta);
  }

  private async setVital(id: string, vitalId: string, value: number): Promise<void> {
    const character = this.repository.snapshot.characters[id];
    const vital = character?.vitals.find((item) => item.id === vitalId);
    if (!character || !vital || !this.canManage()) return;
    const nextValue = Math.max(0, Math.min(vital.max || Number.MAX_SAFE_INTEGER, Math.round(value)));
    await this.repository.upsert({
      ...character,
      session: {
        ...character.session,
        vitalOverrides: { ...character.session.vitalOverrides, [vitalId]: nextValue },
      },
    });
  }

  private async changeStatus(id: string, status: CharacterStatus): Promise<void> {
    if (!this.canManage() || !ALL_STATUSES.includes(status)) return;
    const character = this.repository.snapshot.characters[id];
    if (!character) return;
    await this.repository.upsert({ ...character, session: { ...character.session, status } });
  }

  private async changeSetting(key: string, value: string): Promise<void> {
    if (!this.canManage()) return;
    const current = this.repository.snapshot.settings;
    const next = { ...current } as AppSettings;
    if (key === "autoRefreshMinutes") {
      const parsed = Number(value);
      next.autoRefreshMinutes = ([0, 5, 15, 30].includes(parsed) ? parsed : 0) as AppSettings["autoRefreshMinutes"];
    } else if (key in current) {
      (next as unknown as Record<string, unknown>)[key] = value === "true";
    }
    try {
      await this.repository.updateSettings(next);
      if (key === "autoRefreshMinutes") this.configureAutoRefresh(next.autoRefreshMinutes);
      this.showToast("success", "Configuração salva na cena.");
    } catch (error) {
      this.showToast("error", error instanceof Error ? error.message : "Não foi possível salvar a configuração.");
    }
  }

  private configureAutoRefresh(minutes: number): void {
    if (this.autoRefreshTimer) window.clearInterval(this.autoRefreshTimer);
    this.autoRefreshTimer = undefined;
    if (!minutes || !this.canManage()) return;
    this.autoRefreshTimer = window.setInterval(() => {
      if (document.visibilityState !== "visible" || this.refreshInProgress) return;
      void this.refreshAllCharacters();
    }, minutes * 60_000);
  }

  private async refreshAllCharacters(): Promise<void> {
    if (!this.canManage() || this.refreshInProgress) return;
    this.refreshInProgress = true;
    try {
      const characters = Object.values(this.repository.snapshot.characters);
      for (const character of characters) {
        if (document.visibilityState !== "visible") break;
        try {
          const result = await importCrisCharacter(character.source.url);
          await this.repository.upsert({
            ...result.character,
            id: character.id,
            ...(character.customName ? { customName: character.customName } : {}),
            session: character.session,
            source: { ...result.character.source, importedAt: character.source.importedAt, refreshedAt: Date.now() },
          });
        } catch (error) {
          console.warn("[Sistema-Cris] Atualização automática falhou.", error);
          // Mantém a última versão válida. Uma ficha indisponível não cancela as outras.
        }
      }
    } finally {
      this.refreshInProgress = false;
    }
  }

  private showToast(kind: "success" | "error" | "warning" | "info", message: string): void {
    this.toast = { kind, message };
    this.render(this.repository.snapshot);
    window.setTimeout(() => {
      if (this.toast?.message === message) {
        this.toast = undefined;
        this.render(this.repository.snapshot);
      }
    }, 5_000);
  }

  private canManage(): boolean {
    return !this.isOwlbear || this.role === "GM";
  }

  private displayName(character: CharacterSheet): string {
    return character.customName || character.identity.name || "Agente sem identificação";
  }

  private vitalCurrent(character: CharacterSheet, vitalId: string, original: number): number {
    return character.session.vitalOverrides[vitalId] ?? original;
  }

  private render(state: SceneState): void {
    this.root.classList.toggle("is-compact", state.settings.compactMode);
    this.root.classList.toggle("no-animations", !state.settings.animations);
    const active = this.activeCharacterId ? state.characters[this.activeCharacterId] : undefined;
    const total = Object.keys(state.characters).length;
    const canManage = this.canManage();

    this.root.innerHTML = `
      <div class="app-shell">
        <header class="topbar">
          <div class="brand-mark" aria-hidden="true"><span>C</span><i></i></div>
          <div class="brand-copy"><div class="eyebrow">SISTEMA-CRIS // ARQUIVO DE CAMPO</div><div class="brand-title">SISTEMA-<span>CRIS</span></div></div>
          <button class="icon-button" data-action="settings" aria-label="Configurações" title="Configurações">⚙</button>
        </header>
        <div class="status-strip"><span class="status-dot ${this.sceneReady ? "online" : "offline"}"></span><span>${this.isOwlbear ? (this.sceneReady ? "SINCRONIZADO COM A CENA" : "CACHE LOCAL / SEM CENA") : "MODO DE DESENVOLVIMENTO"}</span><span class="role-label">${this.isOwlbear ? (this.role === "GM" ? "MESTRE" : "JOGADOR") : "LOCAL"}</span></div>
        ${this.toast ? `<div class="toast ${this.toast.kind}" role="status">${escapeHtml(this.toast.message)}</div>` : ""}
        ${this.view === "settings" ? this.renderSettings(state) : active ? this.renderDetail(active, state) : this.renderLibrary(state)}
        <footer class="footer-line"><span>ARQUIVO Nº 0${String(total).padStart(2, "0")}</span><span>ACESSO ${canManage ? "AUTORIZADO" : "SOMENTE LEITURA"}</span><span>v0.2.0</span></footer>
      </div>
    `;

    this.root.querySelectorAll<HTMLImageElement>("img[data-portrait]").forEach((image) => {
      image.addEventListener("error", () => {
        image.classList.add("image-failed");
        image.removeAttribute("src");
      }, { once: true });
    });
    if (this.view === "library" && !active) {
      const input = this.root.querySelector<HTMLInputElement>('input[name="crisUrl"]');
      if (input && this.showImportForm) input.focus();
    }
  }

  private renderLibrary(state: SceneState): string {
    const characters = Object.values(state.characters).sort((a, b) => this.displayName(a).localeCompare(this.displayName(b), "pt-BR"));
    return `
      <main class="content">
        <section class="section-heading">
          <div><div class="eyebrow">REGISTRO DE AGENTES</div><h1>Arquivo <span>de personagens</span></h1><p>Cole o link público de uma ficha do CRIS para carregar todos os dados disponíveis nesta cena.</p></div>
          ${this.canManage() ? `<button class="primary-button compact-button" data-action="toggle-import">${this.showImportForm ? "Fechar" : "+ Adicionar"}</button>` : ""}
        </section>
        ${this.showImportForm && this.canManage() ? this.renderImportForm() : ""}
        ${characters.length ? `
          <div class="list-meta"><span>${characters.length} REGISTRO(S)</span><span>ORDEM ALFABÉTICA</span></div>
          <section class="character-list">${characters.map((character) => this.renderCharacterCard(character)).join("")}</section>
        ` : `
          <section class="empty-state"><div class="empty-symbol">⟡</div><div class="eyebrow">NENHUM REGISTRO</div><h2>Arquivo vazio</h2><p>Adicione uma ficha pública do CRIS para iniciar o arquivo desta cena.</p>${this.canManage() ? `<button class="primary-button" data-action="toggle-import">+ Adicionar personagem</button>` : `<span class="readonly-note">Aguardando o Mestre compartilhar fichas.</span>`}</section>
        `}
        <p class="scope-note">As fichas compartilhadas são guardadas nos metadados da cena atual. O cache IndexedDB mantém uma cópia local de contingência neste navegador.</p>
      </main>
    `;
  }

  private renderImportForm(): string {
    return `
      <form id="import-form" class="import-panel">
        <div class="panel-kicker"><span>01</span> NOVO REGISTRO</div>
        <label for="character-name">Nome de exibição <span>OPCIONAL</span></label>
        <input id="character-name" name="characterName" type="text" maxlength="80" placeholder="Ex.: Arthur Moreira" autocomplete="off" />
        <label for="cris-url">Link público da ficha no CRIS</label>
        <input id="cris-url" name="crisUrl" type="url" required placeholder="https://crisordemparanormal.com/agente/..." autocomplete="url" />
        <button class="primary-button full-width" type="submit" ${this.busy ? "disabled" : ""}>${this.busy ? "IMPORTANDO…" : "IMPORTAR FICHA"}</button>
        <p class="form-footnote">Apenas fichas públicas. Não é solicitado login, senha, cookie ou token do CRIS.</p>
      </form>
    `;
  }

  private renderCharacterCard(character: CharacterSheet): string {
    const name = this.displayName(character);
    const portrait = this.portraitMarkup(character, "card-portrait");
    const vitals = character.vitals.slice(0, 3).map((vital) => {
      const current = this.vitalCurrent(character, vital.id, vital.current);
      return `<span class="mini-vital"><b>${escapeHtml(vital.label)}</b><strong>${current}/${vital.max}</strong></span>`;
    }).join("");
    const identity = [character.identity.className, character.identity.origin].filter(Boolean).join(" • ");
    const nex = character.identity.nex ? `NEX ${character.identity.nex}` : character.identity.level ? `NÍVEL ${character.identity.level}` : "DADOS PARCIAIS";
    return `
      <button class="character-card" data-open="${escapeHtml(character.id)}">
        ${portrait}
        <span class="card-copy"><span class="card-name">${escapeHtml(name)}</span><span class="card-subtitle">${escapeHtml(identity || "Agente da Ordem")}</span><span class="card-meta">${escapeHtml(nex)} <i>•</i> ${escapeHtml(STATUS_LABELS[character.session.status] ?? "Normal")}</span><span class="card-vitals">${vitals || `<span class="mini-vital"><b>PV / PE / SAN</b><strong>SEM DADOS</strong></span>`}</span></span>
        <span class="card-chevron">›</span>
      </button>
    `;
  }

  private renderDetail(character: CharacterSheet, state: SceneState): string {
    const name = this.displayName(character);
    const identity = character.identity;
    const boundToken = this.tokens.find((token) => token.characterId === character.id);
    const sections = character.sections.filter((section) => this.sectionVisible(section, state.settings));
    const additionalEntries = Object.entries(character.additional ?? {});
    const identityRows: Array<[string, string | undefined]> = [
      ["Jogador", identity.player], ["Origem", identity.origin], ["Classe", identity.className],
      ["Trilha", identity.path], ["Patente", identity.rank], ["Organização", identity.organization],
      ["Idade", identity.age], ["Nível", identity.level],
    ];

    return `
      <main class="content detail-content">
        <button class="back-button" data-action="back">← VOLTAR AO ARQUIVO</button>
        <section class="dossier-hero">
          ${this.portraitMarkup(character, "detail-portrait", state.settings.showPhoto)}
          <div class="dossier-identity">
            <div class="eyebrow">DOSSIÊ DE AGENTE // ${escapeHtml(character.source.recordId.slice(0, 8).toUpperCase())}</div>
            <h1>${escapeHtml(name)}</h1>
            <p>${escapeHtml([identity.className, identity.origin].filter(Boolean).join(" • ") || "Identidade incompleta")}</p>
            <span class="nex-stamp">${escapeHtml(identity.nex ? `NEX ${identity.nex}` : identity.level ? `NÍVEL ${identity.level}` : "NEX NÃO INFORMADO")}</span>
          </div>
        </section>

        ${character.vitals.length ? `<section class="panel-section"><div class="panel-heading"><span class="section-index">01</span><h2>ESTADO VITAL</h2><span class="heading-rule"></span></div><div class="vital-grid">${character.vitals.map((vital) => this.renderVital(character, vital)).join("")}</div></section>` : ""}

        <section class="panel-section"><div class="panel-heading"><span class="section-index">02</span><h2>IDENTIFICAÇÃO</h2><span class="heading-rule"></span></div><div class="data-grid">${identityRows.filter(([, value]) => value).map(([label, value]) => `<div class="data-cell"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("") || `<div class="muted-copy">A página não forneceu campos de identificação estruturados.</div>`}</div>${identity.description ? `<div class="description-box">${escapeHtml(identity.description)}</div>` : ""}</section>

        ${state.settings.showAttributes && Object.keys(character.attributes).length ? `<section class="panel-section"><div class="panel-heading"><span class="section-index">03</span><h2>ATRIBUTOS</h2><span class="heading-rule"></span></div><div class="attribute-grid">${Object.entries(character.attributes).map(([key, value]) => `<div class="attribute-cell"><span>${escapeHtml(key)}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}</div></section>` : ""}

        ${Object.keys(character.combat).length ? `<section class="panel-section"><div class="panel-heading"><span class="section-index">04</span><h2>COMBATE</h2><span class="heading-rule"></span></div><div class="data-grid">${Object.entries(character.combat).map(([key, value]) => `<div class="data-cell"><span>${escapeHtml(key)}</span><strong>${escapeHtml(stringifyUnknown(value))}</strong></div>`).join("")}</div></section>` : ""}

        ${sections.map((section) => this.renderSection(section)).join("")}

        ${additionalEntries.length ? `<details class="collapsible-section"><summary><span class="section-index">+</span><span>INFORMAÇÕES ADICIONAIS (${additionalEntries.length})</span><span class="summary-arrow">⌄</span></summary><div class="additional-list">${additionalEntries.map(([key, value]) => `<div class="additional-row"><span>${escapeHtml(key)}</span><pre>${escapeHtml(stringifyUnknown(value))}</pre></div>`).join("")}</div></details>` : ""}

        <section class="panel-section session-panel"><div class="panel-heading"><span class="section-index">05</span><h2>ESTADO DE SESSÃO</h2><span class="heading-rule"></span></div><label class="field-label" for="character-status">Condição atual</label><select id="character-status" ${this.canManage() ? "" : "disabled"}>${ALL_STATUSES.map((status) => `<option value="${status}" ${character.session.status === status ? "selected" : ""}>${escapeHtml(STATUS_LABELS[status])}</option>`).join("")}</select><p class="session-hint">A condição e os ajustes de recursos são dados temporários do Owlbear; não alteram a ficha original do CRIS.</p></section>

        ${this.isOwlbear ? `<section class="panel-section token-panel"><div class="panel-heading"><span class="section-index">06</span><h2>VINCULAÇÃO COM TOKEN</h2><span class="heading-rule"></span></div>${boundToken ? `<div class="bound-token"><span class="bound-dot"></span><div><b>${escapeHtml(boundToken.name)}</b><small>VINCULADO A ESTE AGENTE</small></div></div>` : `<p class="muted-copy">Nenhum Token vinculado a esta ficha.</p>`}<label class="field-label" for="token-picker">Selecionar Token da cena</label><select id="token-picker" ${this.canManage() ? "" : "disabled"}><option value="">Escolher Token…</option>${this.tokens.map((token) => `<option value="${escapeHtml(token.id)}" ${(this.selectedTokenId ?? this.tokenIdFromPopover) === token.id ? "selected" : ""}>${escapeHtml(token.name)}${token.characterId ? " • já vinculado" : ""}</option>`).join("")}</select>${this.canManage() ? `<button class="secondary-button full-width" data-action="link-token">${boundToken ? "VINCULAR / TROCAR TOKEN" : "VINCULAR AO TOKEN"}</button>` : ""}</section>` : ""}

        <section class="source-footer"><div><span>FONTE</span><a href="${escapeHtml(character.source.url)}" target="_blank" rel="noopener noreferrer">ABRIR FICHA NO CRIS ↗</a></div><div><span>ÚLTIMA ATUALIZAÇÃO</span><strong>${escapeHtml(timeAgo(character.source.refreshedAt))}</strong><small>${escapeHtml(formatDate(character.source.refreshedAt))}</small></div></section>

        ${this.canManage() ? `<div class="detail-actions"><button class="secondary-button" data-action="refresh" ${this.busy ? "disabled" : ""}>↻ ATUALIZAR</button><button class="danger-button" data-action="remove">REMOVER</button></div>` : ""}
      </main>
    `;
  }

  private renderVital(character: CharacterSheet, vital: CharacterSheet["vitals"][number]): string {
    const current = this.vitalCurrent(character, vital.id, vital.current);
    const percentage = vital.max > 0 ? Math.max(0, Math.min(100, (current / vital.max) * 100)) : 0;
    return `
      <div class="vital-card" style="--vital-color:${escapeHtml(vital.color)}">
        <div class="vital-top"><span>${escapeHtml(vital.label)}</span><strong>${current}<i> / ${vital.max}</i></strong></div>
        <div class="vital-track"><span style="width:${percentage}%"></span></div>
        ${this.canManage() ? `<div class="vital-controls"><button data-action="vital-minus" data-vital="${escapeHtml(vital.id)}" aria-label="Diminuir ${escapeHtml(vital.label)}">−</button><input type="number" min="0" max="${vital.max}" value="${current}" data-vital-input="${escapeHtml(vital.id)}" aria-label="Valor atual de ${escapeHtml(vital.label)}"/><button data-action="vital-plus" data-vital="${escapeHtml(vital.id)}" aria-label="Aumentar ${escapeHtml(vital.label)}">+</button></div>` : ""}
      </div>
    `;
  }

  private renderSection(section: CharacterSection): string {
    return `
      <details class="collapsible-section" open>
        <summary><span class="section-index">+</span><span>${escapeHtml(section.title.toUpperCase())} (${section.items.length})</span><span class="summary-arrow">⌄</span></summary>
        <div class="section-items">${section.items.map((item) => `
          <article class="record-item"><div class="record-title"><b>${escapeHtml(item.name)}</b>${item.value ? `<strong>${escapeHtml(item.value)}</strong>` : ""}</div>${item.tags?.length ? `<div class="record-tags">${item.tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>` : ""}${item.description ? `<p>${escapeHtml(item.description)}</p>` : ""}${item.extra && Object.keys(item.extra).length ? `<details class="nested-extra"><summary>OUTROS DADOS</summary><pre>${escapeHtml(stringifyUnknown(item.extra))}</pre></details>` : ""}</article>
        `).join("")}</div>
      </details>
    `;
  }

  private renderSettings(state: SceneState): string {
    const settings = state.settings;
    return `
      <main class="content settings-content">
        <button class="back-button" data-action="library">← VOLTAR AO ARQUIVO</button>
        <div class="section-heading"><div><div class="eyebrow">CONFIGURAÇÕES DO SISTEMA</div><h1>Preferências <span>de arquivo</span></h1><p>Opções compartilhadas com a cena atual.</p></div></div>
        <section class="settings-group"><div class="panel-kicker"><span>01</span> ATUALIZAÇÃO</div><label for="setting-autoRefreshMinutes">Atualização automática</label><select id="setting-autoRefreshMinutes" data-setting="autoRefreshMinutes" ${this.canManage() ? "" : "disabled"}><option value="0" ${settings.autoRefreshMinutes === 0 ? "selected" : ""}>Desativada</option><option value="5" ${settings.autoRefreshMinutes === 5 ? "selected" : ""}>A cada 5 minutos</option><option value="15" ${settings.autoRefreshMinutes === 15 ? "selected" : ""}>A cada 15 minutos</option><option value="30" ${settings.autoRefreshMinutes === 30 ? "selected" : ""}>A cada 30 minutos</option></select><p class="session-hint">A atualização só roda enquanto esta extensão estiver aberta e visível. Ao reabrir, os dados em cache continuam disponíveis.</p></section>
        <section class="settings-group"><div class="panel-kicker"><span>02</span> EXIBIÇÃO</div>${this.renderSettingToggle("showPhoto", "Exibir retrato", settings.showPhoto)}${this.renderSettingToggle("showAttributes", "Exibir atributos", settings.showAttributes)}${this.renderSettingToggle("showInventory", "Exibir inventário", settings.showInventory)}${this.renderSettingToggle("showAbilities", "Exibir habilidades e rituais", settings.showAbilities)}${this.renderSettingToggle("compactMode", "Modo compacto", settings.compactMode)}${this.renderSettingToggle("animations", "Animações discretas", settings.animations)}</section>
        <section class="settings-group"><div class="panel-kicker"><span>03</span> ARMAZENAMENTO</div><p class="settings-note">As fichas completas e os vínculos ficam nos metadados da cena atual, compartilhados pelo Owlbear. O cache IndexedDB é local e serve como contingência offline. Os metadados de sala do Owlbear têm limite documentado de 16 kB; por isso, esta extensão não armazena fichas completas nesse espaço.</p><p class="settings-note">O modo Jogador é somente leitura. Apenas o Mestre pode adicionar, remover, atualizar ou alterar dados temporários.</p></section>
      </main>
    `;
  }

  private renderSettingToggle(key: keyof AppSettings, label: string, checked: boolean): string {
    return `<label class="toggle-row"><span>${escapeHtml(label)}</span><select data-setting="${key}" ${this.canManage() ? "" : "disabled"}><option value="true" ${checked ? "selected" : ""}>Ativado</option><option value="false" ${!checked ? "selected" : ""}>Desativado</option></select></label>`;
  }

  private sectionVisible(section: CharacterSection, settings: AppSettings): boolean {
    if (section.id === "inventory" || section.id === "weapons" || section.id === "equipment") return settings.showInventory;
    if (["abilities", "powers", "rituals"].includes(section.id)) return settings.showAbilities;
    return true;
  }

  private portraitMarkup(character: CharacterSheet, className: string, show = true): string {
    const url = show ? safeHttpsUrl(character.avatarUrl) : undefined;
    if (!url) return `<div class="${className} portrait-placeholder"><span>⟡</span><small>SEM RETRATO</small></div>`;
    return `<img class="${className}" data-portrait src="${escapeHtml(url)}" alt="Retrato de ${escapeHtml(this.displayName(character))}" loading="lazy" referrerpolicy="no-referrer" />`;
  }

  dispose(): void {
    this.unsubscribeRepository?.();
    this.unsubscribeSceneReady?.();
    if (this.autoRefreshTimer) window.clearInterval(this.autoRefreshTimer);
    this.repository.dispose();
  }
}
